package com.citacloud.springboot.contacloud.app.services;
import com.citacloud.springboot.contacloud.app.dto.*;import com.citacloud.springboot.contacloud.app.models.*;import com.citacloud.springboot.contacloud.app.repositories.*;import com.citacloud.springboot.contacloud.app.security.*;import org.springframework.dao.DataIntegrityViolationException;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.*;import java.text.Normalizer;import java.util.*;
@Service public class ConfiguracionRecargoService {private final ConfiguracionRecargoVentaRepository configuraciones;private final LimiteRecargoRolRepository limites;private final TipoRecargoRepository tipos;private final MotivoRecargoVentaRepository motivos;private final RolRepository roles;private final MonedaRepository monedas;private final AuditoriaService auditoria;public ConfiguracionRecargoService(ConfiguracionRecargoVentaRepository c,LimiteRecargoRolRepository l,TipoRecargoRepository t,MotivoRecargoVentaRepository m,RolRepository r,MonedaRepository mo,AuditoriaService a){configuraciones=c;limites=l;tipos=t;motivos=m;roles=r;monedas=mo;auditoria=a;}
 @Transactional @PreAuthorize("@empresaModuloService.habilitado('VENTAS') and hasAuthority('recargos_configuracion.ver')") public ConfiguracionRecargoDto obtener(){var p=TenantContext.principalActual();UUID e=EmpresaContext.requerirEmpresaId();return dto(asegurar(p.tenantId(),e,p.usuarioId()),p.tenantId(),e);}
 @Transactional @PreAuthorize("@empresaModuloService.habilitado('VENTAS') and hasAuthority('recargos_configuracion.editar')") public ConfiguracionRecargoDto guardarPolitica(ConfiguracionRecargoInput i){if(i==null)throw new ReglaNegocioException("La configuración es obligatoria.");if(i.habilitado()&&!i.permiteVenta()&&!i.permiteLinea())throw new ReglaNegocioException("Debe habilitar al menos un alcance de recargo: venta completa o productos.");if(i.habilitado()&&!i.permitePorcentaje()&&!i.permiteMonto())throw new ReglaNegocioException("Debe habilitar al menos un tipo de recargo: porcentaje o monto.");var p=TenantContext.principalActual();UUID e=EmpresaContext.requerirEmpresaId();var c=asegurar(p.tenantId(),e,p.usuarioId());if(c.getVersion()!=i.version())throw new ReglaNegocioException("La configuración fue modificada por otro usuario. Actualiza la pantalla.");c.actualizar(i.habilitado(),i.permiteVenta(),i.permiteLinea(),i.permitePorcentaje(),i.permiteMonto(),i.requiereMotivo(),i.permiteAutorizacion(),p.usuarioId());configuraciones.saveAndFlush(c);auditoria.registrar("SALES_SURCHARGE_CONFIGURATION_UPDATED","ConfiguracionRecargoVenta",c.getId(),"{}");return dto(c,p.tenantId(),e);}
 @Transactional @PreAuthorize("@empresaModuloService.habilitado('VENTAS') and hasAuthority('recargos_configuracion.editar')") public void guardarLimite(UUID id,LimiteRecargoInput i){if(i==null||i.rolId()==null)throw new ReglaNegocioException("Selecciona un rol.");BigDecimal pmax=porcentaje(i.porcentajeMaximo()),mmax=monto(i.montoMaximo());if(pmax==null&&mmax==null)throw new ReglaNegocioException("Indica al menos un límite porcentual o monetario.");var p=TenantContext.principalActual();UUID e=EmpresaContext.requerirEmpresaId();Rol rol=roles.findByIdAndEmpresaId(i.rolId(),e).filter(Rol::isActivo).orElseThrow(()->new ReglaNegocioException("El rol seleccionado no está disponible."));LimiteRecargoRol x;if(id==null){if(limites.existsByTenantIdAndEmpresaIdAndRolId(p.tenantId(),e,rol.getId()))throw new ReglaNegocioException("El rol ya tiene límites configurados.");x=new LimiteRecargoRol(p.tenantId(),e,rol.getId(),pmax,mmax,p.usuarioId());}else{x=limites.findByIdAndTenantIdAndEmpresaId(id,p.tenantId(),e).orElseThrow(()->new RecursoNoEncontradoException("Límite no encontrado."));if(i.version()==null||x.getVersion()!=i.version())throw new ReglaNegocioException("El límite fue modificado por otro usuario.");x.actualizar(pmax,mmax,i.activo(),p.usuarioId());}try{x=limites.saveAndFlush(x);}catch(DataIntegrityViolationException ex){throw new ReglaNegocioException("El rol ya tiene límites configurados.",ex);}auditoria.registrar(id==null?"SALES_SURCHARGE_ROLE_LIMIT_CREATED":"SALES_SURCHARGE_ROLE_LIMIT_UPDATED","LimiteRecargoRol",x.getId(),"{}");}
 @Transactional @PreAuthorize("@empresaModuloService.habilitado('VENTAS') and hasAuthority('recargos_configuracion.editar')") public void guardarTipo(UUID id,TipoRecargoInput i){if(i==null||i.tipoPredeterminado()==null)throw new ReglaNegocioException("Selecciona el tipo predeterminado.");String n=texto(i.nombre(),"El nombre del tipo es obligatorio."),nn=normalizar(n);BigDecimal v=i.valorPredeterminado()==null?null:i.valorPredeterminado().setScale(6,RoundingMode.HALF_UP);if(v!=null&&v.signum()<0)throw new ReglaNegocioException("El valor predeterminado no puede ser negativo.");if(i.tipoPredeterminado()==TipoRecargoVenta.PERCENTAGE&&v!=null&&v.compareTo(new BigDecimal("100"))>0)throw new ReglaNegocioException("El porcentaje no puede superar 100%.");var p=TenantContext.principalActual();UUID e=EmpresaContext.requerirEmpresaId();TipoRecargo x;if(id==null){if(tipos.existsByTenantIdAndEmpresaIdAndNombreNormalizado(p.tenantId(),e,nn))throw new ReglaNegocioException("El tipo de recargo ya existe.");x=new TipoRecargo(p.tenantId(),e,n,nn,i.tipoPredeterminado(),v,Optional.ofNullable(i.tratamientoFiscal()).orElse(TratamientoFiscalRecargo.FOLLOW_LINE),i.valorEditable(),p.usuarioId());}else{x=tipos.findByIdAndTenantIdAndEmpresaId(id,p.tenantId(),e).orElseThrow(()->new RecursoNoEncontradoException("Tipo de recargo no encontrado."));if(i.version()==null||x.getVersion()!=i.version())throw new ReglaNegocioException("El tipo fue modificado por otro usuario.");if(tipos.existsByTenantIdAndEmpresaIdAndNombreNormalizadoAndIdNot(p.tenantId(),e,nn,id))throw new ReglaNegocioException("El tipo de recargo ya existe.");x.actualizar(n,nn,i.tipoPredeterminado(),v,Optional.ofNullable(i.tratamientoFiscal()).orElse(TratamientoFiscalRecargo.FOLLOW_LINE),i.valorEditable(),i.activo(),p.usuarioId());}tipos.saveAndFlush(x);auditoria.registrar(id==null?"SALES_SURCHARGE_TYPE_CREATED":"SALES_SURCHARGE_TYPE_UPDATED","TipoRecargo",x.getId(),"{}");}
 @Transactional @PreAuthorize("@empresaModuloService.habilitado('VENTAS') and hasAuthority('recargos_configuracion.editar')") public void guardarMotivo(UUID id,MotivoRecargoInput i){if(i==null)throw new ReglaNegocioException("Los datos del motivo son obligatorios.");String n=texto(i.nombre(),"El nombre del motivo es obligatorio."),nn=normalizar(n);var p=TenantContext.principalActual();UUID e=EmpresaContext.requerirEmpresaId();MotivoRecargoVenta x;if(id==null){if(motivos.existsByTenantIdAndEmpresaIdAndNombreNormalizado(p.tenantId(),e,nn))throw new ReglaNegocioException("El motivo ya existe.");x=new MotivoRecargoVenta(p.tenantId(),e,n,nn,i.otro(),p.usuarioId());}else{x=motivos.findByIdAndTenantIdAndEmpresaId(id,p.tenantId(),e).orElseThrow(()->new RecursoNoEncontradoException("Motivo no encontrado."));if(i.version()==null||x.getVersion()!=i.version())throw new ReglaNegocioException("El motivo fue modificado por otro usuario.");if(motivos.existsByTenantIdAndEmpresaIdAndNombreNormalizadoAndIdNot(p.tenantId(),e,nn,id))throw new ReglaNegocioException("El motivo ya existe.");x.actualizar(n,nn,i.otro(),i.activo(),p.usuarioId());}motivos.saveAndFlush(x);auditoria.registrar(id==null?"SALES_SURCHARGE_REASON_CREATED":"SALES_SURCHARGE_REASON_UPDATED","MotivoRecargoVenta",x.getId(),"{}");}
 ConfiguracionRecargoVenta asegurar(UUID t,UUID e,UUID u){return configuraciones.findByTenantIdAndEmpresaId(t,e).orElseGet(()->configuraciones.saveAndFlush(new ConfiguracionRecargoVenta(t,e,u)));}
 private ConfiguracionRecargoDto dto(ConfiguracionRecargoVenta c,UUID t,UUID e){String moneda=monedas.findByEmpresaIdAndMonedaBaseTrue(e).map(Moneda::getCodigoIso).orElse("—");var ls=limites.listar(t,e).stream().map(x->new ConfiguracionRecargoDto.Limite(x.getId(),x.getRolId(),x.getRol().getNombre(),x.getPorcentajeMaximo(),x.getMontoMaximo(),x.isActivo(),x.getVersion())).toList();var ts=tipos.findAllByTenantIdAndEmpresaIdOrderByNombre(t,e).stream().map(x->new ConfiguracionRecargoDto.Tipo(x.getId(),x.getNombre(),x.getTipoPredeterminado(),x.getValorPredeterminado(),x.getTratamientoFiscal(),x.isValorEditable(),x.isActivo(),x.getVersion())).toList();var ms=motivos.findAllByTenantIdAndEmpresaIdOrderByNombre(t,e).stream().map(x->new ConfiguracionRecargoDto.Motivo(x.getId(),x.getNombre(),x.isOtro(),x.isActivo(),x.getVersion())).toList();var rs=roles.findAllByEmpresaIdAndActivoTrueOrderByNombre(e).stream().map(x->new ConfiguracionRecargoDto.RolOpcion(x.getId(),x.getNombre())).toList();return new ConfiguracionRecargoDto(c.isEnabled(),c.isPermiteVenta(),c.isPermiteLinea(),c.isPermitePorcentaje(),c.isPermiteMonto(),c.isRequiereMotivo(),c.isPermiteAutorizacion(),c.getVersion(),moneda,ls,ts,ms,rs);}
 private static BigDecimal porcentaje(BigDecimal v){if(v==null)return null;v=v.setScale(4,RoundingMode.HALF_UP);if(v.signum()<0||v.compareTo(new BigDecimal("100"))>0)throw new ReglaNegocioException("El porcentaje debe estar entre 0 y 100.");return v;}private static BigDecimal monto(BigDecimal v){if(v==null)return null;v=v.setScale(4,RoundingMode.HALF_UP);if(v.signum()<0)throw new ReglaNegocioException("El monto máximo no puede ser negativo.");return v;}private static String texto(String v,String msg){String x=v==null?"":v.trim();if(x.isEmpty())throw new ReglaNegocioException(msg);if(x.length()>120)throw new ReglaNegocioException("El nombre excede 120 caracteres.");return x;}private static String normalizar(String v){return Normalizer.normalize(v,Normalizer.Form.NFD).replaceAll("\\p{M}","").toLowerCase(Locale.ROOT).replaceAll("\\s+"," ").trim();}}
